from pathlib import Path
import json,html
P=Path(__file__).resolve().parent.parent
icons=json.loads((P/'source/icons.json').read_text())
def I(n): return icons.get(n,'')
def link(text,target,cls=''): return f'<a class="{cls}" href="{target}.html">{text}</a>'
def btn(text,target,secondary=False): return link(text+I('ArrowRight'),target,'button'+(' secondary' if secondary else ''))
def img(file,alt,cls=''): return f'<img class="{cls}" src="../assets/{file}.png" alt="{alt}">'
def label(text): return f'<span class="eyebrow">{text}</span>'
def field(name,value='',wide=False,error='',typ='text',readonly=False):
 id='f-'+''.join(c for c in name if c.isalnum()).lower()
 return f'<div class="field {"wide" if wide else ""}"><label for="{id}">{name}</label><input id="{id}" type="{typ}" value="{value}" {"readonly aria-readonly=true" if readonly else ""} {"aria-invalid=true aria-describedby="+id+"-error" if error else ""}>{"<span class=error-text id="+id+"-error>"+error+"</span>" if error else ""}</div>'
def note(text,kind='info'): return f'<div class="note {kind}">{I("Info") if kind!="success" else I("CheckCircle2")}<span>{text}</span></div>'
